"use client";

import { useState, useEffect } from "react";
import { Loader2, X, IndianRupee } from "lucide-react";

export interface SettleInvoiceData {
  id: string;
  invoiceNumber: string;
  customerName: string;
  total: number;
  amountPaid: number;
}

interface SettleModalProps {
  isOpen: boolean;
  onClose: () => void;
  invoice: SettleInvoiceData | null;
  onSuccess: () => void;
}

export default function SettleModal({ isOpen, onClose, invoice, onSuccess }: SettleModalProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const amountDue = invoice ? invoice.total - invoice.amountPaid : 0;

  const [amountPaying, setAmountPaying] = useState<string>("");
  const [paymentMode, setPaymentMode] = useState<string>("CASH");

  // Reset form when modal opens with a new invoice
  useEffect(() => {
    if (isOpen && invoice) {
      const due = invoice.total - invoice.amountPaid;
      setAmountPaying(due > 0 ? String(due) : "");
      setPaymentMode("CASH");
      setError("");
    }
  }, [isOpen, invoice]);

  if (!isOpen || !invoice) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    const amount = Number(amountPaying);
    if (isNaN(amount) || amount <= 0) {
      setError("Please enter a valid amount");
      return;
    }

    if (amount > amountDue) {
      setError(`Amount cannot exceed the due amount (₹${amountDue})`);
      return;
    }

    setLoading(true);
    try {
      const res = await fetch(`/api/invoices/${invoice.id}/settle`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amountPaid: amount, paymentMode })
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Failed to settle payment");
      }

      onSuccess();
      onClose();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" style={{ zIndex: 9999 }}>
      <div className="legacy-window" style={{ width: '380px', maxWidth: '100%', fontSize: '11px', color: 'black' }}>
        <div className="legacy-window-titlebar">
          <div className="title-text">
            Settle Payment
          </div>
          <button className="legacy-btn-close" type="button" onClick={onClose} title="Close">
            <X size={12} strokeWidth={3} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-3" style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {error && (
            <div style={{ padding: '6px', backgroundColor: '#fff', border: '1px solid #808080', color: 'red' }}>
              {error}
            </div>
          )}

          <div style={{ backgroundColor: '#fff', border: '1px solid #808080', padding: '8px' }}>
            <div className="flex justify-between mb-1">
              <span>Invoice:</span>
              <span className="font-bold">#{invoice.invoiceNumber} ({invoice.customerName})</span>
            </div>
            <div className="flex justify-between mb-1">
              <span>Total Bill:</span>
              <span className="font-bold">₹{invoice.total.toLocaleString('en-IN')}</span>
            </div>
            <div className="flex justify-between mb-1">
              <span>Paid So Far:</span>
              <span className="font-bold">₹{invoice.amountPaid.toLocaleString('en-IN')}</span>
            </div>
            <div className="pt-2 mt-1 border-t border-gray-300 flex justify-between font-bold" style={{ fontSize: '12px' }}>
              <span>Amount Due:</span>
              <span style={{ color: '#000' }}>₹{amountDue.toLocaleString('en-IN')}</span>
            </div>
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '4px' }}>
              Paying Amount <span style={{ color: 'red' }}>*</span>
            </label>
            <div className="flex items-center">
              <span className="mr-1">₹</span>
              <input
                type="number"
                required
                min="1"
                max={amountDue}
                step="any"
                value={amountPaying}
                onChange={(e) => setAmountPaying(e.target.value)}
                className="legacy-input w-full"
                placeholder="0.00"
              />
            </div>
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '4px' }}>
              Payment Mode <span style={{ color: 'red' }}>*</span>
            </label>
            <select
              required
              value={paymentMode}
              onChange={(e) => setPaymentMode(e.target.value)}
              className="legacy-input w-full"
            >
              <option value="CASH">Cash</option>
              <option value="UPI">UPI</option>
              <option value="CARD">Card</option>
            </select>
          </div>

          <div className="pt-2 flex justify-end gap-2 mt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={loading}
              className="legacy-button"
              style={{ minWidth: '80px' }}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="legacy-button flex items-center gap-1 justify-center"
              style={{ minWidth: '130px', fontWeight: 'bold' }}
            >
              {loading ? <Loader2 size={12} className="animate-spin" /> : <IndianRupee size={12} />}
              Confirm Payment
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback, Suspense } from "react";
import Link from "next/link";
import { Plus, Search, FileText, Loader2, Printer, IndianRupee, Edit3, Download } from "lucide-react";
import { formatCurrency, formatDate, PAYMENT_STATUS_COLORS } from "@/lib/utils";
import { useToast } from "@/contexts/ToastContext";
import { useRouter, useSearchParams } from "next/navigation";
import PageHeader from "@/components/layout/PageHeader";
import SettleModal, { SettleInvoiceData } from "./SettleModal";
import NewBillDialog from "@/components/billing/NewBillDialog";
import EditBillDialog from "@/components/billing/EditBillDialog";

interface Invoice {
  id: string;
  invoiceNumber: string;
  subtotal: number;
  discount: number;
  gst: number;
  total: number;
  amountPaid: number;
  paymentMode: string;
  paymentStatus: string;
  type: string;
  dueDate: string | null;
  createdAt: string;
  customer: { id: string; name: string; mobile: string };
  items: any[];
}

const PAYMENT_MODE_LABELS: Record<string, string> = {
  CASH: "Cash",
  UPI: "UPI",
  CARD: "Card",
  PENDING: "Pending",
};

function BillingContent() {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const searchParams = useSearchParams();
  const [statusFilter, setStatusFilter] = useState(searchParams.get("paymentStatus") || "");
  const [settleInvoice, setSettleInvoice] = useState<SettleInvoiceData | null>(null);
  const [isNewBillOpen, setIsNewBillOpen] = useState(false);
  const [editingInvoiceId, setEditingInvoiceId] = useState<string | null>(null);
  const toast = useToast();
  const router = useRouter();
  const limit = 20;

  const fetchInvoices = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        q: query,
        page: String(page),
        limit: String(limit),
      });
      if (statusFilter) params.set("paymentStatus", statusFilter);

      const res = await fetch(`/api/invoices?${params.toString()}`);
      const data = await res.json();
      setInvoices(data.invoices || []);
      setTotal(data.total || 0);
    } catch {
      toast.error("Failed to load invoices");
    } finally {
      setLoading(false);
    }
  }, [query, page, statusFilter, toast]);

  const handleSettleInvoice = (invoice: Invoice) => {
    setSettleInvoice({
      id: invoice.id,
      invoiceNumber: invoice.invoiceNumber,
      customerName: invoice.customer.name,
      total: invoice.total,
      amountPaid: invoice.amountPaid || 0,
    });
  };

  const handleDeleteInvoice = async (invoiceId: string) => {
    if (!confirm("Are you sure you want to delete this invoice?")) return;
    try {
      const res = await fetch(`/api/invoices/${invoiceId}`, { method: 'DELETE' });
      if (!res.ok) throw new Error("Failed to delete invoice");
      toast.success("Invoice deleted successfully");
      fetchInvoices();
    } catch {
      toast.error("Failed to delete invoice");
    }
  };

  const handleExportCSV = () => {
    if (!invoices || invoices.length === 0) {
      toast.error("No invoices available to export");
      return;
    }
    const headers = ["Invoice Number", "Date", "Customer Name", "Mobile", "Subtotal (INR)", "Discount (INR)", "GST (%)", "Total Amount (INR)", "Amount Paid (INR)", "Balance Due (INR)", "Payment Mode", "Payment Status"];
    const rows = invoices.map(inv => [
      `"${inv.invoiceNumber}"`,
      `"${new Date(inv.createdAt).toLocaleDateString("en-IN")}"`,
      `"${inv.customer.name.replace(/"/g, '""')}"`,
      `"${inv.customer.mobile}"`,
      inv.subtotal || 0,
      inv.discount || 0,
      inv.gst || 0,
      inv.total || 0,
      inv.amountPaid || 0,
      Math.max(0, inv.total - (inv.amountPaid || 0)),
      `"${inv.paymentMode}"`,
      `"${inv.paymentStatus}"`
    ]);

    const csvContent = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `RA_Seva_Point_Invoices_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success("Sales report exported successfully!");
  };

  useEffect(() => {
    const timer = setTimeout(fetchInvoices, 300);
    return () => clearTimeout(timer);
  }, [fetchInvoices]);

  const totalPages = Math.ceil(total / limit);

  return (
    <div className="page-shell page-shell-list">
      <PageHeader
        title="Billing & Invoices"
        subtitle={`${total} total invoice${total === 1 ? "" : "s"} generated`}
        actions={
          <div className="flex gap-2">
            <button type="button" className="btn-secondary flex items-center gap-1 text-xs font-bold" onClick={handleExportCSV}>
              <Download size={14} />
              Export Sales (CSV)
            </button>
            <button type="button" className="btn-primary flex items-center gap-1 text-xs font-bold" onClick={() => setIsNewBillOpen(true)}>
              <Plus size={16} />
              Create Invoice
            </button>
          </div>
        }
      />
      <NewBillDialog
        isOpen={isNewBillOpen}
        onClose={() => setIsNewBillOpen(false)}
        onSuccess={fetchInvoices}
      />

      {/* Search & Filters */}
      <div className="toolbar">
        <div className="search-field">
          <Search size={14} />
          <input
            type="text"
            placeholder="Search by invoice number, customer name or mobile..."
            className="input-field"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setPage(1);
            }}
          />
        </div>

        {/* Payment Status Filter */}
        <select
          className="input-field"
          style={{ maxWidth: 180 }}
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value);
            setPage(1);
          }}
        >
          <option value="">All Status</option>
          <option value="UNPAID">Unpaid</option>
          <option value="PARTIAL">Partial</option>
          <option value="PAID">Paid</option>
        </select>
      </div>

      {/* Invoices List */}
      {loading ? (
        <div className="flex items-center justify-center h-48">
          <Loader2 size={28} className="animate-spin" style={{ color: "var(--brand-primary)" }} />
        </div>
      ) : invoices.length === 0 ? (
        <div className="empty-state">
          <FileText size={56} className="empty-state-icon" />
          <div className="empty-state-title">No invoices found</div>
          <div className="empty-state-desc">
            {query || statusFilter
              ? "No results match your search/filter criteria."
              : "Create your first invoice to record a sale."}
          </div>
          {!query && !statusFilter && (
            <button type="button" onClick={() => setIsNewBillOpen(true)} className="btn-primary mt-4">
              <Plus size={16} />
              Create Invoice
            </button>
          )}
        </div>
      ) : (
        <>
          <div
            style={{
              backgroundColor: "#ffffff",
              borderTop: "2px solid #808080",
              borderLeft: "2px solid #808080",
              borderRight: "2px solid #ffffff",
              borderBottom: "2px solid #ffffff",
              overflowX: "auto",
              boxShadow: "inset 1px 1px 2px rgba(0,0,0,0.2)",
            }}
          >
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px", fontFamily: "Tahoma, 'MS Sans Serif', sans-serif" }}>
              <thead>
                <tr style={{ backgroundColor: "#d4d0c8", borderBottom: "2px solid #808080" }}>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Invoice #</th>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Customer Name</th>
                  <th style={{ padding: "6px 10px", textAlign: "center", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Items</th>
                  <th style={{ padding: "6px 10px", textAlign: "center", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Payment Status</th>
                  <th style={{ padding: "6px 10px", textAlign: "center", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Mode</th>
                  <th style={{ padding: "6px 10px", textAlign: "right", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Total Amount</th>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: "bold", borderRight: "1px solid #808080", color: "#000000" }}>Date</th>
                  <th style={{ padding: "6px 10px", textAlign: "center", fontWeight: "bold", color: "#000000" }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {invoices.map((inv, index) => (
                  <tr
                    key={inv.id}
                    onClick={() => router.push(`/billing/${inv.id}`)}
                    style={{
                      backgroundColor: index % 2 === 0 ? "#ffffff" : "#f9f9f6",
                      borderBottom: "1px solid #e2e8f0",
                      cursor: "pointer",
                    }}
                    className="hover:bg-blue-50 transition-colors"
                  >
                    <td style={{ padding: "8px 10px", fontWeight: "bold", color: "#000080" }}>
                      #{inv.invoiceNumber}
                      {inv.type === "QUOTATION" && (
                        <span style={{ marginLeft: "6px", fontSize: "9px", background: "orange", color: "white", padding: "2px 4px", borderRadius: "2px" }}>
                          QUOTATION
                        </span>
                      )}
                    </td>
                    <td style={{ padding: "8px 10px" }}>
                      <div style={{ fontWeight: "bold", color: "#0f172a" }}>{inv.customer.name}</div>
                      <div style={{ fontSize: "10px", color: "#64748b" }}>📞 {inv.customer.mobile}</div>
                    </td>
                    <td style={{ padding: "8px 10px", textAlign: "center", color: "#334155" }}>
                      {inv.items.length} item{inv.items.length !== 1 ? "s" : ""}
                    </td>
                    <td style={{ padding: "8px 10px", textAlign: "center" }}>
                      <span
                        style={{
                          background: inv.paymentStatus === "PAID" ? "#166534" : inv.paymentStatus === "PARTIAL" ? "#ca8a04" : "#dc2626",
                          color: "#ffffff",
                          fontWeight: "bold",
                          padding: "2px 8px",
                          borderRadius: "2px",
                          fontSize: "10px",
                        }}
                      >
                        {inv.paymentStatus}
                      </span>
                    </td>
                    <td style={{ padding: "8px 10px", textAlign: "center", fontWeight: "bold", color: "#475569" }}>
                      {PAYMENT_MODE_LABELS[inv.paymentMode] || inv.paymentMode}
                    </td>
                    <td style={{ padding: "8px 10px", textAlign: "right", fontWeight: "900", color: "#0f172a" }}>
                      {formatCurrency(inv.total)}
                    </td>
                    <td style={{ padding: "8px 10px", color: "#475569" }}>
                      {formatDate(inv.createdAt)}
                    </td>
                    <td style={{ padding: "8px 10px", textAlign: "center" }} onClick={(e) => e.stopPropagation()}>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "4px" }}>
                        <Link
                          href={`/billing/${inv.id}`}
                          style={{
                            backgroundColor: "#d4d0c8",
                            borderTop: "2px solid #ffffff",
                            borderLeft: "2px solid #ffffff",
                            borderRight: "2px solid #404040",
                            borderBottom: "2px solid #404040",
                            padding: "2px 6px",
                            fontWeight: "bold",
                            fontSize: "11px",
                            color: "#000000",
                            textDecoration: "none",
                          }}
                        >
                          View
                        </Link>
                        {inv.paymentStatus !== "PAID" && (
                          <button
                            type="button"
                            onClick={() => handleSettleInvoice(inv)}
                            style={{
                              backgroundColor: "#166534",
                              color: "#ffffff",
                              borderTop: "2px solid #ffffff",
                              borderLeft: "2px solid #ffffff",
                              borderRight: "2px solid #14532d",
                              borderBottom: "2px solid #14532d",
                              padding: "2px 6px",
                              fontWeight: "bold",
                              fontSize: "11px",
                              cursor: "pointer",
                            }}
                          >
                            Settle
                          </button>
                        )}
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            setEditingInvoiceId(inv.id);
                          }}
                          style={{
                            backgroundColor: "#d4d0c8",
                            borderTop: "2px solid #ffffff",
                            borderLeft: "2px solid #ffffff",
                            borderRight: "2px solid #404040",
                            borderBottom: "2px solid #404040",
                            padding: "2px 6px",
                            fontWeight: "bold",
                            fontSize: "11px",
                            color: "#000000",
                            cursor: "pointer",
                          }}
                          title="Edit Invoice"
                        >
                          Edit
                        </button>
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDeleteInvoice(inv.id);
                          }}
                          style={{
                            backgroundColor: "#d4d0c8",
                            borderTop: "2px solid #ffffff",
                            borderLeft: "2px solid #ffffff",
                            borderRight: "2px solid #404040",
                            borderBottom: "2px solid #404040",
                            padding: "2px 6px",
                            fontWeight: "bold",
                            fontSize: "11px",
                            color: "#000000",
                            cursor: "pointer",
                          }}
                          title="Delete Invoice"
                        >
                          Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between pt-4">
              <span className="text-sm" style={{ color: "var(--text-muted)" }}>
                Showing {(page - 1) * limit + 1}–{Math.min(page * limit, total)} of {total}
              </span>
              <div className="flex items-center gap-2">
                <button
                  className="btn-secondary"
                  disabled={page === 1}
                  onClick={() => setPage(page - 1)}
                >
                  Previous
                </button>
                <span className="text-sm font-semibold" style={{ color: "var(--text-secondary)" }}>
                  {page} / {totalPages}
                </span>
                <button
                  className="btn-secondary"
                  disabled={page >= totalPages}
                  onClick={() => setPage(page + 1)}
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </>
      )}

      <SettleModal 
        isOpen={!!settleInvoice}
        onClose={() => setSettleInvoice(null)}
        invoice={settleInvoice}
        onSuccess={() => {
          toast.success("Payment settled successfully");
          fetchInvoices();
        }}
      />

      <EditBillDialog
        isOpen={!!editingInvoiceId}
        onClose={() => setEditingInvoiceId(null)}
        invoiceId={editingInvoiceId}
        onSuccess={fetchInvoices}
      />
    </div>
  );
}

export default function BillingPage() {
  return (
    <Suspense fallback={<div className="p-8 flex justify-center"><Loader2 className="animate-spin text-emerald-600" /></div>}>
      <BillingContent />
    </Suspense>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { BookOpen, Search, Plus, Loader2, Save, X, AlertTriangle } from "lucide-react";
import { useToast } from "@/contexts/ToastContext";
import { formatCurrency, BOOK_CATEGORIES } from "@/lib/utils";
import PageHeader from "@/components/layout/PageHeader";

interface Book {
  id: string;
  name: string;
  author?: string;
  category?: string;
  purchasePrice: number;
  sellingPrice: number;
  quantity: number;
  minStock: number;
  barcode?: string;
}

export default function BookStorePage() {
  const toast = useToast();
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const [form, setForm] = useState({
    name: "",
    author: "",
    category: BOOK_CATEGORIES[0] as string,
    purchasePrice: "",
    sellingPrice: "",
    quantity: "",
    minStock: "5",
    barcode: "",
  });

  const fetchBooks = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/books?q=${encodeURIComponent(query)}`);
      const data = await res.json();
      setBooks(data || []);
    } catch {
      toast.error("Failed to load books");
    } finally {
      setLoading(false);
    }
  }, [query, toast]);

  useEffect(() => {
    const t = setTimeout(fetchBooks, 300);
    return () => clearTimeout(t);
  }, [fetchBooks]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name || !form.purchasePrice || !form.sellingPrice || !form.quantity) {
      toast.error("Please fill in all required fields");
      return;
    }
    setSaving(true);
    try {
      const res = await fetch("/api/books", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      if (!res.ok) throw new Error("Failed to save book");
      toast.success("Book registered successfully!");
      setModalOpen(false);
      setForm({
        name: "",
        author: "",
        category: BOOK_CATEGORIES[0] as string,
        purchasePrice: "",
        sellingPrice: "",
        quantity: "",
        minStock: "5",
        barcode: "",
      });
      fetchBooks();
    } catch {
      toast.error("Failed to add book");
    } finally {
      setSaving(false);
    }
  };

  const lowStockBooks = books.filter((b) => b.quantity <= b.minStock);

  return (
    <div className="page-shell page-shell-list">
      <PageHeader
        title="Book Store"
        subtitle={`${books.length} titles registered in stock`}
        actions={
          <button onClick={() => setModalOpen(true)} className="btn-primary">
            <Plus size={16} />
            Add Book
          </button>
        }
      />

      {/* Low Stock Alerts */}
      {lowStockBooks.length > 0 && (
        <div className="p-4 rounded-2xl flex gap-3 items-start bg-amber-500/10 border border-amber-500/20 text-amber-600">
          <AlertTriangle size={18} className="shrink-0 mt-0.5" />
          <div>
            <div className="font-bold text-sm">Low Stock Alert</div>
            <p className="text-xs mt-0.5">
              {lowStockBooks.length} book titles are running below minimum stock alert thresholds.
            </p>
          </div>
        </div>
      )}

      {/* Search */}
      <div className="toolbar">
        <div className="search-field">
          <Search size={16} />
          <input
            type="text"
            placeholder="Search by title, author, genre or barcode..."
            className="input-field"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
      </div>

      {/* List / Table */}
      {loading ? (
        <div className="flex items-center justify-center h-48">
          <Loader2 size={28} className="animate-spin" style={{ color: "var(--brand-primary)" }} />
        </div>
      ) : books.length === 0 ? (
        <div className="empty-state">
          <BookOpen size={56} className="empty-state-icon" />
          <div className="empty-state-title">No books in catalog</div>
          <div className="empty-state-desc">Add your first book title to start selling.</div>
        </div>
      ) : (
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Title & Author</th>
                <th>Category</th>
                <th>Purchase (₹)</th>
                <th>Selling (₹)</th>
                <th>In Stock</th>
                <th>Alert Threshold</th>
              </tr>
            </thead>
            <tbody>
              {books.map((book) => (
                <tr key={book.id}>
                  <td>
                    <div>
                      <div className="font-semibold text-sm" style={{ color: "var(--text-primary)" }}>{book.name}</div>
                      <div className="text-xs" style={{ color: "var(--text-muted)" }}>{book.author || "Unknown Author"}</div>
                    </div>
                  </td>
                  <td>
                    <span className="text-sm font-semibold" style={{ color: "var(--text-secondary)" }}>{book.category}</span>
                  </td>
                  <td className="text-sm" style={{ color: "var(--text-secondary)" }}>{formatCurrency(book.purchasePrice)}</td>
                  <td className="font-bold text-sm" style={{ color: "var(--text-primary)" }}>{formatCurrency(book.sellingPrice)}</td>
                  <td>
                    <span className={`badge ${book.quantity <= book.minStock ? "badge-cancelled" : "badge-approved"}`}>
                      {book.quantity} units
                    </span>
                  </td>
                  <td className="text-sm" style={{ color: "var(--text-muted)" }}>{book.minStock} units</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Add Book Modal */}
      {modalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2 className="section-title mb-0">Register Book</h2>
              <button onClick={() => setModalOpen(false)} className="btn-ghost p-1">
                <X size={16} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="modal-body space-y-4">
              <div>
                <label className="label">Book Title *</label>
                <input
                  type="text"
                  className="input-field"
                  placeholder="e.g. CBSE Physics Class 12"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label">Author</label>
                  <input
                    type="text"
                    className="input-field"
                    placeholder="e.g. HC Verma"
                    value={form.author}
                    onChange={(e) => setForm({ ...form, author: e.target.value })}
                  />
                </div>
                <div>
                  <label className="label">Category</label>
                  <select
                    className="input-field"
                    value={form.category}
                    onChange={(e) => setForm({ ...form, category: e.target.value })}
                  >
                    {BOOK_CATEGORIES.map((cat) => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label">Purchase Price (₹) *</label>
                  <input
                    type="number"
                    className="input-field"
                    placeholder="0.00"
                    value={form.purchasePrice}
                    onChange={(e) => setForm({ ...form, purchasePrice: e.target.value })}
                    required
                  />
                </div>
                <div>
                  <label className="label">Selling Price (₹) *</label>
                  <input
                    type="number"
                    className="input-field"
                    placeholder="0.00"
                    value={form.sellingPrice}
                    onChange={(e) => setForm({ ...form, sellingPrice: e.target.value })}
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label">Quantity in Stock *</label>
                  <input
                    type="number"
                    className="input-field"
                    placeholder="0"
                    value={form.quantity}
                    onChange={(e) => setForm({ ...form, quantity: e.target.value })}
                    required
                  />
                </div>
                <div>
                  <label className="label">Min Stock Threshold</label>
                  <input
                    type="number"
                    className="input-field"
                    placeholder="5"
                    value={form.minStock}
                    onChange={(e) => setForm({ ...form, minStock: e.target.value })}
                  />
                </div>
              </div>

              <div className="modal-footer pt-4">
                <button type="button" onClick={() => setModalOpen(false)} className="btn-secondary">Cancel</button>
                <button type="submit" className="btn-primary" disabled={saving}>
                  {saving ? "Registering..." : "Add Book"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useMemo, useRef, useState } from "react";
import {
  Copy,
  Download,
  ExternalLink,
  Eye,
  EyeOff,
  MessageSquare,
  Plus,
  Printer,
  Save,
  Star,
  Trash2,
  Upload,
  WalletCards,
} from "lucide-react";
import PageHeader from "@/components/layout/PageHeader";
import { SERVICE_CATALOG, type ServiceCatalogItem } from "@/lib/serviceCatalog";
import { formatCurrency } from "@/lib/utils";
import { useToast } from "@/contexts/ToastContext";
import { useDownload } from "@/contexts/DownloadContext";

type PrintJob = {
  id: string;
  name: string;
  customer: string;
  status: "Pending" | "Printed" | "Delivered";
};

type Credential = {
  id: string;
  portal: string;
  username: string;
  password: string;
  note: string;
};

type CashClosing = {
  cash: string;
  upi: string;
  card: string;
  expense: string;
};

const useStoredState = <T,>(key: string, initialValue: T) => {
  const [value, setValue] = useState<T>(() => {
    if (typeof window === "undefined") return initialValue;
    const saved = window.localStorage.getItem(key);
    if (!saved) return initialValue;
    try {
      return JSON.parse(saved) as T;
    } catch {
      return initialValue;
    }
  });

  const setStoredValue = (next: T) => {
    setValue(next);
    window.localStorage.setItem(key, JSON.stringify(next));
  };

  return [value, setStoredValue] as const;
};

const buildWhatsAppText = (service: ServiceCatalogItem, customerName: string) =>
  service.message.replace("{name}", customerName || "customer");

export default function CounterDeskPage() {
  const toast = useToast();
  const { downloadWithRename } = useDownload();
  const [activeTab, setActiveTab] = useState<"favorites" | "print" | "credentials" | "cash">("favorites");
  const importInputRef = useRef<HTMLInputElement>(null);

  const [query, setQuery] = useState("");
  const [selectedServiceId, setSelectedServiceId] = useState(SERVICE_CATALOG[0]?.id || "");
  const [customerName, setCustomerName] = useState("");
  const [printName, setPrintName] = useState("");
  const [printCustomer, setPrintCustomer] = useState("");
  const [cashClosing, setCashClosing] = useStoredState<CashClosing>("ra-counter-cash-closing", {
    cash: "",
    upi: "",
    card: "",
    expense: "",
  });
  const [printQueue, setPrintQueue] = useStoredState<PrintJob[]>("ra-counter-print-queue", []);
  const [favorites, setFavorites] = useStoredState<string[]>("ra-counter-favorites", []);
  const [credentials, setCredentials] = useStoredState<Credential[]>("ra-counter-credentials", []);
  const [credentialForm, setCredentialForm] = useState({ portal: "", username: "", password: "", note: "" });
  const [showPasswords, setShowPasswords] = useState(false);

  const filteredServices = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return SERVICE_CATALOG;
    return SERVICE_CATALOG.filter((service) =>
      [service.name, service.category, service.documents.join(" ")]
        .join(" ")
        .toLowerCase()
        .includes(normalized)
    );
  }, [query]);

  const selectedService =
    SERVICE_CATALOG.find((service) => service.id === selectedServiceId) || SERVICE_CATALOG[0];

  const totals = {
    cash: Number(cashClosing.cash) || 0,
    upi: Number(cashClosing.upi) || 0,
    card: Number(cashClosing.card) || 0,
    expense: Number(cashClosing.expense) || 0,
  };
  const grossTotal = totals.cash + totals.upi + totals.card;
  const netTotal = grossTotal - totals.expense;

  const copyText = async (text: string, label: string) => {
    await navigator.clipboard.writeText(text);
    toast.success(`${label} copied`);
  };

  const toggleFavorite = (id: string) => {
    setFavorites(favorites.includes(id) ? favorites.filter((item) => item !== id) : [...favorites, id]);
  };

  const addPrintJob = () => {
    if (!printName.trim()) {
      toast.error("Print item name required");
      return;
    }
    setPrintQueue([
      {
        id: `${Date.now()}`,
        name: printName.trim(),
        customer: printCustomer.trim() || "Walk-in",
        status: "Pending",
      },
      ...printQueue,
    ]);
    setPrintName("");
    setPrintCustomer("");
  };

  const updatePrintStatus = (id: string, status: PrintJob["status"]) => {
    setPrintQueue(printQueue.map((job) => (job.id === id ? { ...job, status } : job)));
  };

  const addCredential = () => {
    if (!credentialForm.portal.trim() || !credentialForm.username.trim()) {
      toast.error("Portal and username required");
      return;
    }
    setCredentials([{ id: `${Date.now()}`, ...credentialForm }, ...credentials]);
    setCredentialForm({ portal: "", username: "", password: "", note: "" });
  };

  const exportCounterData = () => {
    const payload = {
      exportedAt: new Date().toISOString(),
      favorites,
      printQueue,
      cashClosing,
      credentials: credentials.map((item) => ({ ...item, password: item.password ? "Saved locally" : "" })),
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    downloadWithRename(url, `RA_Counter_Backup_${Date.now()}.json`);
    // URL will be revoked later or handled by the system
  };

  const importCounterData = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result;
        if (typeof text !== "string") throw new Error("Unreadable file");
        const parsed = JSON.parse(text);

        if (
          typeof parsed !== "object" ||
          parsed === null ||
          !("favorites" in parsed) ||
          !("printQueue" in parsed) ||
          !("cashClosing" in parsed)
        ) {
          throw new Error("Missing required fields");
        }

        if (Array.isArray(parsed.favorites)) {
          setFavorites(parsed.favorites as string[]);
        }
        if (Array.isArray(parsed.printQueue)) {
          setPrintQueue(parsed.printQueue as PrintJob[]);
        }
        if (typeof parsed.cashClosing === "object" && parsed.cashClosing !== null) {
          setCashClosing(parsed.cashClosing as CashClosing);
        }

        toast.success("Counter data imported!");
      } catch {
        toast.error("Invalid or corrupt JSON file. Import failed.");
      } finally {
        // Reset the input so the same file can be re-imported if needed
        if (importInputRef.current) {
          importInputRef.current.value = "";
        }
      }
    };
    reader.readAsText(file);
  };

  const hasDeliveredJobs = printQueue.some((job) => job.status === "Delivered");

  return (
    <div className="page-shell page-shell-list">
      {/* Hidden file input for import */}
      <input
        ref={importInputRef}
        type="file"
        accept=".json"
        className="hidden"
        onChange={importCounterData}
        aria-hidden="true"
      />

      <PageHeader
        title="Counter Desk"
        subtitle="Rate list, document checklist, WhatsApp templates, print queue and daily cash closing"
        actions={
          <div className="flex items-center gap-2">
            <button type="button" className="btn-secondary" onClick={() => importInputRef.current?.click()}>
              <Upload size={16} />
              Import Data
            </button>
            <button type="button" className="btn-secondary" onClick={exportCounterData}>
              <Download size={16} />
              Export Counter Data
            </button>
          </div>
        }
      />

      <div className="metric-grid">
        <div className="stat-card">
          <span className="label">Services</span>
          <p className="text-2xl font-bold">{SERVICE_CATALOG.length}</p>
        </div>
        <div className="stat-card">
          <span className="label">Print Queue</span>
          <p className="text-2xl font-bold">{printQueue.filter((job) => job.status !== "Delivered").length}</p>
        </div>
        <div className="stat-card">
          <span className="label">Daily Net</span>
          <p className="text-2xl font-bold">{formatCurrency(netTotal)}</p>
        </div>
      </div>

      <div className="content-grid content-grid-wide">
        <section className="glass-card p-4">
          <div className="flex items-center justify-between gap-3 mb-3">
            <h2 className="section-title mb-0">Service Rate List</h2>
            <input
              className="input-field max-w-[280px]"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search service..."
            />
          </div>

          <div className="table-wrapper">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Service</th>
                  <th>Fee</th>
                  <th>Time</th>
                  <th>Docs</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {filteredServices.map((service) => (
                  <tr key={service.id}>
                    <td>
                      <button
                        type="button"
                        className="font-bold text-left"
                        onClick={() => setSelectedServiceId(service.id)}
                      >
                        {service.name}
                      </button>
                      <div className="text-xs">{service.category}</div>
                    </td>
                    <td className="font-bold">{formatCurrency(service.fee)}</td>
                    <td>{service.estimate}</td>
                    <td>{service.documents.length}</td>
                    <td>
                      <div className="flex items-center justify-end gap-1">
                        <button type="button" className="btn-ghost p-1" onClick={() => toggleFavorite(service.id)} title="Favorite">
                          <Star size={14} fill={favorites.includes(service.id) ? "currentColor" : "none"} />
                        </button>
                        {service.portal && (
                          <a className="btn-ghost p-1" href={service.portal} target="_blank" rel="noreferrer" title="Open portal">
                            <ExternalLink size={14} />
                          </a>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        <aside className="panel-stack">
          <section className="glass-card p-4">
            <h2 className="section-title">Required Documents</h2>
            <p className="font-bold text-sm">{selectedService.name}</p>
            <div className="flex flex-wrap gap-2 mt-3">
              {selectedService.documents.map((doc) => (
                <span key={doc} className="badge badge-submitted">{doc}</span>
              ))}
            </div>
            <button
              type="button"
              className="btn-secondary w-full mt-3"
              onClick={() => copyText(selectedService.documents.join(", "), "Document list")}
            >
              <Copy size={14} />
              Copy Documents
            </button>
          </section>

          <section className="glass-card p-4">
            <h2 className="section-title">WhatsApp Template</h2>
            <input
              className="input-field mb-2"
              value={customerName}
              onChange={(event) => setCustomerName(event.target.value)}
              placeholder="Customer name"
            />
            <div className="info-tile text-sm leading-relaxed">
              {buildWhatsAppText(selectedService, customerName)}
            </div>
            <button
              type="button"
              className="btn-primary w-full mt-3"
              onClick={() => copyText(buildWhatsAppText(selectedService, customerName), "WhatsApp message")}
            >
              <MessageSquare size={14} />
              Copy Message
            </button>
          </section>
        </aside>
      </div>

      <div className="content-grid content-grid-wide">
        <section className="glass-card p-4">
          <div className="flex items-center justify-between mb-3">
            <h2 className="section-title mb-0">Print Queue</h2>
            {hasDeliveredJobs && (
              <button
                type="button"
                className="btn-secondary"
                onClick={() => setPrintQueue(printQueue.filter((job) => job.status !== "Delivered"))}
              >
                <Trash2 size={14} />
                Clear All Delivered
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-[1fr_1fr_auto] gap-2 mb-3">
            <input className="input-field" value={printName} onChange={(event) => setPrintName(event.target.value)} placeholder="Document name" />
            <input className="input-field" value={printCustomer} onChange={(event) => setPrintCustomer(event.target.value)} placeholder="Customer name" />
            <button type="button" className="btn-primary" onClick={addPrintJob}>
              <Plus size={14} />
              Add
            </button>
          </div>
          <div className="space-y-2">
            {printQueue.length === 0 ? (
              <div className="empty-state py-8">No print jobs</div>
            ) : (
              printQueue.map((job) => (
                <div key={job.id} className="file-row">
                  <Printer size={16} />
                  <div>
                    <p className="font-bold text-sm">{job.name}</p>
                    <p className="text-xs">{job.customer}</p>
                  </div>
                  <select className="input-field" value={job.status} onChange={(event) => updatePrintStatus(job.id, event.target.value as PrintJob["status"])}>
                    <option>Pending</option>
                    <option>Printed</option>
                    <option>Delivered</option>
                  </select>
                  <button type="button" className="btn-ghost p-1" onClick={() => setPrintQueue(printQueue.filter((item) => item.id !== job.id))}>
                    <Trash2 size={14} />
                  </button>
                </div>
              ))
            )}
          </div>
        </section>

        <section className="glass-card p-4">
          <h2 className="section-title">Daily Cash Closing</h2>
          <div className="form-grid form-grid-2">
            {[
              ["cash", "Cash"],
              ["upi", "UPI"],
              ["card", "Card"],
              ["expense", "Expense"],
            ].map(([key, label]) => (
              <div key={key}>
                <label className="label">{label}</label>
                <input
                  className="input-field"
                  type="number"
                  value={cashClosing[key as keyof CashClosing]}
                  onChange={(event) => setCashClosing({ ...cashClosing, [key]: event.target.value })}
                />
              </div>
            ))}
          </div>
          <div className="info-grid mt-3">
            <div className="info-tile">
              <span className="label">Gross</span>
              <p className="font-bold">{formatCurrency(grossTotal)}</p>
            </div>
            <div className="info-tile">
              <span className="label">Net</span>
              <p className="font-bold">{formatCurrency(netTotal)}</p>
            </div>
          </div>
        </section>
      </div>

      <section className="glass-card p-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="section-title mb-0">Portal Credential Vault</h2>
          <button type="button" className="btn-secondary" onClick={() => setShowPasswords(!showPasswords)}>
            {showPasswords ? <EyeOff size={14} /> : <Eye size={14} />}
            {showPasswords ? "Hide" : "Show"}
          </button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-[1fr_1fr_1fr_1fr_auto] gap-2 mb-3">
          <input className="input-field" value={credentialForm.portal} onChange={(event) => setCredentialForm({ ...credentialForm, portal: event.target.value })} placeholder="Portal" />
          <input className="input-field" value={credentialForm.username} onChange={(event) => setCredentialForm({ ...credentialForm, username: event.target.value })} placeholder="Username" />
          <input className="input-field" value={credentialForm.password} onChange={(event) => setCredentialForm({ ...credentialForm, password: event.target.value })} placeholder="Password" type={showPasswords ? "text" : "password"} />
          <input className="input-field" value={credentialForm.note} onChange={(event) => setCredentialForm({ ...credentialForm, note: event.target.value })} placeholder="Note" />
          <button type="button" className="btn-primary" onClick={addCredential}>
            <Save size={14} />
            Save
          </button>
        </div>
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Portal</th>
                <th>Username</th>
                <th>Password</th>
                <th>Note</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {credentials.map((item) => (
                <tr key={item.id}>
                  <td>{item.portal}</td>
                  <td>{item.username}</td>
                  <td>{showPasswords ? item.password : "••••••••"}</td>
                  <td>{item.note}</td>
                  <td>
                    <button type="button" className="btn-ghost p-1" onClick={() => setCredentials(credentials.filter((credential) => credential.id !== item.id))}>
                      <Trash2 size={14} />
                    </button>
                  </td>
                </tr>
              ))}
              {credentials.length === 0 && (
                <tr>
                  <td colSpan={5}>No credentials saved. Data stays in this browser local storage.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <p className="text-xs mt-2" style={{ color: "var(--text-muted)" }}>
          Sensitive data yahan browser ke local storage me save hota hai. Shared computer par password save na karein.
        </p>
      </section>
    </div>
  );
}

"use client";

import { useState, useEffect, use } from "react";
import { useRouter } from "next/navigation";
import { User, Phone, Mail, MapPin, Loader2, ChevronRight, FileText, Plus, Trash2, Edit, X, MessageCircle, Check } from "lucide-react";
import { useToast } from "@/contexts/ToastContext";
import { formatCurrency, formatDate, SERVICE_STATUS_COLORS, PAYMENT_STATUS_COLORS } from "@/lib/utils";
import PageHeader from "@/components/layout/PageHeader";
import ServiceDetailsDialog from "@/components/services/ServiceDetailsDialog";
import InvoiceDetailsDialog from "@/components/billing/InvoiceDetailsDialog";
import LegacyDialog from "@/components/layout/LegacyDialog";

export default function CustomerDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  const router = useRouter();
  const toast = useToast();
  const [customer, setCustomer] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<"services" | "invoices" | "documents">("services");
  const [docForm, setDocForm] = useState({ name: "", type: "Document", url: "" });

  const [showEditModal, setShowEditModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editForm, setEditForm] = useState({ 
    name: "", mobile: "", email: "", address: "", aadhaarNumber: "", panNumber: "" 
  });
  const [selectedServiceId, setSelectedServiceId] = useState<string | null>(null);
  const [selectedInvoiceId, setSelectedInvoiceId] = useState<string | null>(null);
  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);

  const fetchCustomer = () => {
    fetch(`/api/customers/${resolvedParams.id}`)
      .then((res) => {
        if (!res.ok) throw new Error("Customer profile not found");
        return res.json();
      })
      .then((data) => {
        setCustomer(data);
        setEditForm({
          name: data.name || "",
          mobile: data.mobile || "",
          email: data.email || "",
          address: data.address || "",
          aadhaarNumber: data.aadhaarNumber || "",
          panNumber: data.panNumber || "",
        });
        setLoading(false);
      })
      .catch((err) => {
        toast.error(err.message);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchCustomer();
  }, [resolvedParams.id]);

  const refreshCustomer = async () => {
    const res = await fetch(`/api/customers/${resolvedParams.id}`);
    if (!res.ok) return;
    const data = await res.json();
    setCustomer(data);
    setEditForm({
      name: data.name || "",
      mobile: data.mobile || "",
      email: data.email || "",
      address: data.address || "",
      aadhaarNumber: data.aadhaarNumber || "",
      panNumber: data.panNumber || "",
    });
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      const res = await fetch(`/api/customers/${resolvedParams.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(editForm),
      });
      if (!res.ok) throw new Error("Failed to update customer");
      await refreshCustomer();
      toast.success("Customer updated successfully");
      setShowEditModal(false);
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!confirm("Are you sure you want to delete this customer? This cannot be undone.")) return;
    try {
      const res = await fetch(`/api/customers/${resolvedParams.id}`, { method: "DELETE" });
      if (!res.ok) throw new Error("Failed to delete customer");
      toast.success("Customer deleted");
      router.push("/customers");
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const addDocument = async () => {
    if (!docForm.name.trim()) {
      toast.error("Document name required");
      return;
    }
    const res = await fetch(`/api/customers/${resolvedParams.id}/documents`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(docForm),
    });
    if (!res.ok) {
      toast.error("Document save failed");
      return;
    }
    setDocForm({ name: "", type: "Document", url: "" });
    await refreshCustomer();
    toast.success("Document saved");
  };

  const deleteDocument = async (documentId: string) => {
    const res = await fetch(`/api/documents/${documentId}`, { method: "DELETE" });
    if (!res.ok) {
      toast.error("Document delete failed");
      return;
    }
    await refreshCustomer();
    toast.success("Document deleted");
  };

  const sendWhatsApp = (text?: string) => {
    if (!customer?.mobile) return toast.error("Mobile number not found");
    const message = text || `Hello ${customer.name},\n`;
    const url = `https://wa.me/91${customer.mobile}?text=${encodeURIComponent(message)}`;
    window.open(url, "_blank");
  };

  const handleSettleInvoice = async (invoiceId: string) => {
    const amount = prompt("Enter amount paid by customer:");
    if (!amount || isNaN(Number(amount))) return;

    try {
      const res = await fetch(`/api/invoices/${invoiceId}/settle`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amountPaid: Number(amount) })
      });
      if (!res.ok) throw new Error("Failed to settle payment");
      toast.success("Payment settled");
      await refreshCustomer();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  // Khata ledger calculations
  const totalBilled = customer?.invoices?.reduce((sum: number, inv: any) => sum + (inv.total || 0), 0) || 0;
  const totalPaid = customer?.invoices?.reduce((sum: number, inv: any) => sum + (inv.amountPaid || 0), 0) || 0;
  const totalDue = Math.max(0, totalBilled - totalPaid);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      setDocForm((prev) => ({
        ...prev,
        name: prev.name || file.name,
        url: base64,
      }));
      toast.success("File attached! Click Add to save.");
    };
    reader.readAsDataURL(file);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 size={32} className="animate-spin" style={{ color: "var(--brand-primary)" }} />
      </div>
    );
  }

  return (
    <div className="page-shell page-shell-detail">
      <PageHeader
        title={customer.name}
        subtitle={`Registered on ${formatDate(customer.createdAt)}`}
        backHref="/customers"
        actions={
          <div className="flex gap-2">
            <button 
              onClick={() => sendWhatsApp()} 
              className="btn-secondary text-green-600 border-green-200 bg-green-50 hover:bg-green-100"
            >
              <MessageCircle size={16} /> WhatsApp
            </button>
            <button onClick={() => setShowEditModal(true)} className="btn-secondary text-blue-600 border-blue-200 bg-blue-50 hover:bg-blue-100">
              <Edit size={16} /> Edit
            </button>
            <button onClick={handleDelete} className="btn-secondary text-red-600 border-red-200 bg-red-50 hover:bg-red-100">
              <Trash2 size={16} /> Delete
            </button>
          </div>
        }
      />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Profile & Khata Card */}
        <div className="space-y-4">
          <div className="glass-card p-6 space-y-4">
            <h2 className="section-title flex items-center gap-2 mb-0">
              <User size={18} className="text-blue-500" />
              Customer Profile
            </h2>
            <hr style={{ borderColor: "var(--border-primary)" }} />

            <div className="space-y-3 text-sm">
              <div className="flex items-center gap-2">
                <Phone size={14} className="text-slate-400 shrink-0" />
                <span style={{ color: "var(--text-primary)" }}>{customer.mobile}</span>
              </div>

              {customer.email && (
                <div className="flex items-center gap-2">
                  <Mail size={14} className="text-slate-400 shrink-0" />
                  <span style={{ color: "var(--text-primary)" }}>{customer.email}</span>
                </div>
              )}

              {customer.address && (
                <div className="flex items-start gap-2">
                  <MapPin size={14} className="text-slate-400 shrink-0 mt-0.5" />
                  <span style={{ color: "var(--text-primary)" }}>{customer.address}</span>
                </div>
              )}
            </div>

            <hr style={{ borderColor: "var(--border-primary)" }} />

            <div className="space-y-2">
              <div>
                <span className="label">Aadhaar Number</span>
                <p className="text-sm font-semibold" style={{ color: "var(--text-primary)" }}>
                  {customer.aadhaarNumber || "Not Provided"}
                </p>
              </div>
              <div>
                <span className="label">PAN Number</span>
                <p className="text-sm font-semibold uppercase" style={{ color: "var(--text-primary)" }}>
                  {customer.panNumber || "Not Provided"}
                </p>
              </div>
              <div className="pt-2 border-t mt-2" style={{ borderColor: "var(--border-primary)" }}>
                <span className="label flex items-center gap-1">⭐ Loyalty Points</span>
                <p className="text-xl font-bold text-yellow-600">
                  {customer.loyaltyPoints || 0}
                </p>
              </div>
            </div>
          </div>

          {/* Khata Ledger Summary Card (Windows 95 Classic Bevel Window Style) */}
          <div
            style={{
              backgroundColor: "#d4d0c8",
              borderTop: "2px solid #ffffff",
              borderLeft: "2px solid #ffffff",
              borderRight: "2px solid #404040",
              borderBottom: "2px solid #404040",
              padding: "2px",
              boxShadow: "2px 2px 5px rgba(0,0,0,0.2)",
            }}
          >
            {/* Title Bar */}
            <div
              style={{
                background: "linear-gradient(to right, #000080 0%, #1084d0 100%)",
                color: "#ffffff",
                padding: "3px 6px",
                fontWeight: "bold",
                fontSize: "12px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                <FileText size={13} color="#ffffff" />
                <span style={{ color: "#ffffff", fontWeight: "bold" }}>KHATA LEDGER ACCOUNT</span>
              </div>
              {totalDue > 0 && (
                <span
                  style={{
                    background: "#b91c1c",
                    color: "#ffffff",
                    fontSize: "10px",
                    fontWeight: "bold",
                    padding: "1px 6px",
                    borderRadius: "2px",
                    border: "1px solid #ffffff",
                  }}
                >
                  UDHAAR ACTIVE
                </span>
              )}
            </div>

            {/* Inset White Content Box */}
            <div
              style={{
                backgroundColor: "#ffffff",
                borderTop: "2px solid #808080",
                borderLeft: "2px solid #808080",
                borderRight: "2px solid #ffffff",
                borderBottom: "2px solid #ffffff",
                padding: "10px",
                marginTop: "2px",
              }}
            >
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px", paddingBottom: "8px", borderBottom: "1px solid #d4d0c8" }}>
                <div>
                  <div style={{ fontSize: "10px", fontWeight: "bold", color: "#444444", textTransform: "uppercase" }}>LIFETIME BILLED</div>
                  <div style={{ fontSize: "14px", fontWeight: "900", color: "#000080" }}>{formatCurrency(totalBilled)}</div>
                </div>
                <div>
                  <div style={{ fontSize: "10px", fontWeight: "bold", color: "#444444", textTransform: "uppercase" }}>TOTAL RECEIVED</div>
                  <div style={{ fontSize: "14px", fontWeight: "900", color: "#008000" }}>{formatCurrency(totalPaid)}</div>
                </div>
              </div>

              <div style={{ paddingTop: "8px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <div>
                  <div style={{ fontSize: "10px", fontWeight: "bold", color: "#444444", textTransform: "uppercase" }}>PENDING DUE BALANCE</div>
                  <div style={{ fontSize: "18px", fontWeight: "900", color: totalDue > 0 ? "#cc0000" : "#008000" }}>
                    {formatCurrency(totalDue)}
                  </div>
                </div>
              </div>

              {totalDue > 0 && (
                <button
                  type="button"
                  onClick={() => sendWhatsApp(`Namaste ${customer.name} ji! 🙏\n\nRA Seva Point se aapka total pending due (udhaar) *${formatCurrency(totalDue)}* baaki hai.\n\nKripya ise jald se jald cash ya UPI dwara bhugtan karein.\n\nDhanyawad! 📱 RA Seva Point`)}
                  style={{
                    width: "100%",
                    marginTop: "10px",
                    padding: "6px 8px",
                    backgroundColor: "#d4d0c8",
                    borderTop: "2px solid #ffffff",
                    borderLeft: "2px solid #ffffff",
                    borderRight: "2px solid #404040",
                    borderBottom: "2px solid #404040",
                    color: "#000000",
                    fontSize: "11px",
                    fontWeight: "bold",
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: "6px",
                  }}
                >
                  <MessageCircle size={15} color="#25D366" />
                  <span>Send Due Reminder on WhatsApp</span>
                </button>
              )}

              <button
                type="button"
                onClick={() => {
                  window.open(`/print/ledger/${customer.id}`, '_blank');
                }}
                style={{
                  width: "100%",
                  marginTop: "8px",
                  padding: "6px 8px",
                  backgroundColor: "#d4d0c8",
                  borderTop: "2px solid #ffffff",
                  borderLeft: "2px solid #ffffff",
                  borderRight: "2px solid #404040",
                  borderBottom: "2px solid #404040",
                  color: "#000000",
                  fontSize: "11px",
                  fontWeight: "bold",
                  cursor: "pointer",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: "6px",
                }}
              >
                <FileText size={15} color="#000080" />
                <span>Print Khata Ledger PDF</span>
              </button>
            </div>
          </div>
        </div>

        {/* History Tabs */}
        <div className="md:col-span-2 space-y-4">
          <div className="segmented-control full" role="tablist" aria-label="Customer history">
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === "services"}
              onClick={() => setActiveTab("services")}
              className={`segmented-item ${activeTab === "services" ? "active" : ""}`}
            >
              Services ({customer.services?.length || 0})
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === "invoices"}
              onClick={() => setActiveTab("invoices")}
              className={`segmented-item ${activeTab === "invoices" ? "active" : ""}`}
            >
              Invoices ({customer.invoices?.length || 0})
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === "documents"}
              onClick={() => setActiveTab("documents")}
              className={`segmented-item ${activeTab === "documents" ? "active" : ""}`}
            >
              Documents ({customer.documents?.length || 0})
            </button>
          </div>

          {/* Services Tab */}
          {activeTab === "services" && (
            <div className="space-y-3">
              {customer.services?.length === 0 ? (
                <div className="text-center py-12 glass-card text-sm text-slate-400">
                  No service records found.
                </div>
              ) : (
                customer.services.map((s: any) => (
                  <div
                    key={s.id}
                    className="glass-card p-4 flex items-center justify-between cursor-pointer hover:bg-slate-50 transition-colors"
                    onClick={() => { setSelectedServiceId(s.id); setIsServiceModalOpen(true); }}
                  >
                    <div>
                      <div className="font-bold text-sm" style={{ color: "var(--text-primary)" }}>
                        {s.serviceType}
                      </div>
                      <div className="text-xs text-slate-400 mt-1">
                        Registered: {formatDate(s.createdAt)}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`badge ${SERVICE_STATUS_COLORS[s.status]}`}>
                        {s.status}
                      </span>
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          sendWhatsApp(`Hello ${customer.name}, your service application for ${s.serviceType} is currently ${s.status}.`);
                        }}
                        className="p-2 text-green-500 hover:bg-green-50 rounded-full transition-colors"
                        title="Send WhatsApp update"
                      >
                        <MessageCircle size={16} />
                      </button>
                      <ChevronRight size={16} style={{ color: "var(--text-muted)" }} />
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {/* Invoices Tab */}
          {activeTab === "invoices" && (
            <div className="space-y-3">
              {customer.invoices?.length === 0 ? (
                <div className="text-center py-12 glass-card text-sm text-slate-400">
                  No billing records found.
                </div>
              ) : (
                customer.invoices.map((inv: any) => (
                  <div
                    key={inv.id}
                    className="glass-card p-4 flex items-center justify-between cursor-pointer hover:bg-slate-50 transition-colors"
                    onClick={() => setSelectedInvoiceId(inv.id)}
                  >
                    <div>
                      <div className="font-mono font-bold text-sm" style={{ color: "var(--brand-primary)" }}>
                        #{inv.invoiceNumber}
                      </div>
                      <div className="text-xs text-slate-400 mt-1">
                        {formatDate(inv.createdAt)} · Total: {formatCurrency(inv.total)}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`badge ${PAYMENT_STATUS_COLORS[inv.paymentStatus]}`}>
                        {inv.paymentStatus}
                      </span>

                      {inv.paymentStatus !== "PAID" && (
                        <button 
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleSettleInvoice(inv.id);
                          }}
                          className="btn-secondary px-2 py-1 text-xs"
                          style={{ color: "#059669", backgroundColor: "rgba(5, 150, 105, 0.1)", borderColor: "rgba(5, 150, 105, 0.2)" }}
                        >
                          Settle
                        </button>
                      )}

                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          sendWhatsApp(`Hello ${customer.name}, your invoice #${inv.invoiceNumber} for amount ${formatCurrency(inv.total)} has a pending due of ${formatCurrency(inv.total - (inv.amountPaid || 0))}. Please settle it at your earliest convenience.`);
                        }}
                        className="p-1 text-green-500 hover:bg-green-50 rounded"
                        title="Send Reminder"
                      >
                        <MessageCircle size={14} />
                      </button>

                      <ChevronRight size={16} style={{ color: "var(--text-muted)" }} />
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {/* Documents Tab */}
          {activeTab === "documents" && (
            <div className="space-y-4">
              <div className="glass-card p-4 space-y-3">
                <h2 className="section-title flex items-center gap-2 mb-0">
                  <FileText size={16} className="text-blue-600" />
                  Customer Document Folder
                </h2>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                  <input
                    className="input-field"
                    value={docForm.name}
                    onChange={(e) => setDocForm({ ...docForm, name: e.target.value })}
                    placeholder="Document Name (e.g. Aadhaar Card)..."
                  />
                  <select
                    className="input-field"
                    value={docForm.type}
                    onChange={(e) => setDocForm({ ...docForm, type: e.target.value })}
                  >
                    <option value="Aadhaar Card">Aadhaar Card</option>
                    <option value="PAN Card">PAN Card</option>
                    <option value="Passport Photo">Passport Photo</option>
                    <option value="Income Certificate">Income Certificate</option>
                    <option value="Caste Certificate">Caste Certificate</option>
                    <option value="Marksheet">Marksheet</option>
                    <option value="Other">Other Document</option>
                  </select>

                  <div className="flex items-center gap-2">
                    <input
                      type="file"
                      id="doc-file-input"
                      className="hidden"
                      onChange={handleFileUpload}
                    />
                    <label
                      htmlFor="doc-file-input"
                      className="btn-secondary text-xs px-3 py-2 cursor-pointer truncate max-w-[130px]"
                      title="Upload file from device"
                    >
                      {docForm.url ? "File Attached ✓" : "Choose File..."}
                    </label>
                    <button type="button" className="btn-primary flex-1 py-2 text-xs" onClick={addDocument}>
                      <Plus size={14} />
                      Save Doc
                    </button>
                  </div>
                </div>

                <div className="text-[11px] text-slate-400">
                  Tip: Upload Aadhaar, PAN, Photos or Certificates directly to save them permanently for future form applications.
                </div>
              </div>

              {customer.documents?.length === 0 ? (
                <div className="text-center py-12 glass-card text-sm text-slate-400">
                  No documents saved for this customer.
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {customer.documents.map((doc: any) => (
                    <div key={doc.id} className="glass-card p-4 flex items-center justify-between gap-3 border border-slate-200 hover:shadow-md transition-shadow">
                      <div className="truncate">
                        <div className="font-bold text-sm truncate" style={{ color: "var(--text-primary)" }}>
                          {doc.name}
                        </div>
                        <div className="text-xs text-slate-500 mt-0.5">
                          Category: <span className="font-semibold text-blue-600">{doc.type}</span> · {formatDate(doc.createdAt)}
                        </div>
                        {doc.url && (
                          <a
                            href={doc.url}
                            target="_blank"
                            rel="noreferrer"
                            className="text-xs font-semibold underline mt-1 inline-block text-blue-600 hover:text-blue-800"
                          >
                            Preview / Download
                          </a>
                        )}
                      </div>
                      <button
                        type="button"
                        className="btn-ghost p-2 text-red-500 hover:bg-red-50 rounded"
                        onClick={() => deleteDocument(doc.id)}
                        title="Delete Document"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {showEditModal && (
