import { formatCurrency, formatDate } from "@/lib/utils";
import * as XLSX from "xlsx";
import LegacyDialog from "@/components/layout/LegacyDialog";

interface Income {
  id: string;
  category: string;
  amount: number;
  description: string | null;
  date: string;
  createdAt: string;
}

const INCOME_CATEGORIES = [
  "Commission",
  "Scrap Sale",
  "Other Shop Income",
  "Interest",
  "Refund",
  "Other"
];

export default function IncomeTab() {
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [query, setQuery] = useState("");
  const [month, setMonth] = useState(() => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
  });

  const [form, setForm] = useState({
    category: INCOME_CATEGORIES[0],
    amount: "",
    description: "",
    date: new Date().toISOString().split("T")[0]
  });
  const [modalOpen, setModalOpen] = useState(false);

  const toast = useToast();

  const fetchIncomes = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (month) params.set("month", month);
      if (query) params.set("q", query);

      const res = await fetch(`/api/income?${params}`);
      const data = await res.json();
      setIncomes(data.income || []);
    } catch (err) {
      toast.error("Failed to load income records");
    } finally {
      setLoading(false);
    }
  }, [month, query, toast]);

  useEffect(() => {
    const t = setTimeout(() => {
      fetchIncomes();
    }, 300);
    return () => clearTimeout(t);
  }, [fetchIncomes]);

  const handleAddIncome = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.amount || parseFloat(form.amount) <= 0) {
      toast.error("Please enter a valid amount");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/income", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          category: form.category === "Other" && form.description 
            ? `Other - ${form.description.split(" ")[0]}` 
            : form.category,
          amount: parseFloat(form.amount),
          description: form.description,
          date: form.date,
        }),
      });

      if (!res.ok) throw new Error("Failed to add income");
      toast.success("Income added successfully");

      setForm({
        category: INCOME_CATEGORIES[0],
        amount: "",
        description: "",
        date: new Date().toISOString().split("T")[0]
      });
      setModalOpen(false);
      fetchIncomes();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this income record?")) return;
    try {
      const res = await fetch(`/api/income/${id}`, { method: "DELETE" });
      if (!res.ok) throw new Error("Failed to delete");
      toast.success("Income deleted");
      fetchIncomes();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const totalIncome = incomes.reduce((sum, inc) => sum + inc.amount, 0);

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(
      incomes.map(inc => ({
        Date: formatDate(inc.date),
        Category: inc.category,
        Description: inc.description || "",
        Amount: inc.amount
      }))
    );
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Income");
    XLSX.writeFile(wb, `Income_${month}.xlsx`);
  };

  const exportPDF = async () => {
    try {
      const { jsPDF } = await import("jspdf");
      const { default: autoTable } = await import("jspdf-autotable");

      const doc = new jsPDF();
      doc.text(`Income Report (${month})`, 14, 15);

      autoTable(doc, {
        startY: 20,
        head: [["Date", "Category", "Description", "Amount"]],
        body: incomes.map(inc => [
          formatDate(inc.date),
          inc.category,
          inc.description || "-",
          inc.amount.toFixed(2)
        ]),
        foot: [["", "", "Total", totalIncome.toFixed(2)]],
        theme: 'grid'
      });

      doc.save(`Income_${month}.pdf`);
    } catch (error) {
      console.error("Failed to generate PDF", error);
      toast.error("Failed to generate PDF");
    }
  };

  return (
    <div className="space-y-4 mt-4">
      {/* Summary Card */}
        <div className="glass-card p-6 border-l-4 border-emerald-500">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
              <ArrowUpCircle size={24} />
            </div>
            <div>
              <p className="text-sm font-semibold" style={{ color: "var(--text-muted)" }}>Total Extra Income (Selected Month)</p>
              <h3 className="text-3xl font-black mt-1" style={{ color: "var(--text-primary)" }}>
                {formatCurrency(totalIncome)}
              </h3>
            </div>
          </div>
        </div>

      {/* Income List */}
      <div className="glass-card p-6 flex flex-col h-full">
        <div className="flex flex-col sm:flex-row gap-3 mb-6">
          <div className="flex-1 relative">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: "var(--text-muted)" }} />
            <input
              type="text"
              placeholder="Search income..."
              className="input-field pl-9"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          </div>
          <div className="relative">
            <CalendarDays size={14} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: "var(--text-muted)" }} />
            <input
              type="month"
              className="input-field pl-9 w-40"
