"use client";

import { useState, useRef, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Download, Upload, Trash2, Eye } from "lucide-react";
import { ReactTransliterate } from "react-transliterate";
import "react-transliterate/dist/index.css";
import { biharRationNewConfig, biharRationNewSchema, type BiharRationNewData } from "@/config/forms/bihar-ration-new";
import BiharRationNewTemplate from "@/components/templates/BiharRationNewTemplate";

export default function RationCardNewApplyForm() {
  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
  const [signaturePreview, setSignaturePreview] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  // Ref to the unscaled engine container
  const engineRef = useRef<HTMLDivElement>(null);

  const { register, handleSubmit, watch, setValue, formState: { errors } } = useForm<BiharRationNewData>({
    resolver: zodResolver(biharRationNewSchema),
    defaultValues: {
      familyMembers: Array(6).fill({}),
    }
  });

  const formData = watch();

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'photo' | 'signature') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = type === 'signature' ? 400 : 300;
          const MAX_HEIGHT = type === 'signature' ? 150 : 400;
          let width = img.width;
          let height = img.height;

          if (width > height) {
            if (width > MAX_WIDTH) {
              height *= MAX_WIDTH / width;
              width = MAX_WIDTH;
            }
          } else {
            if (height > MAX_HEIGHT) {
              width *= MAX_HEIGHT / height;
              height = MAX_HEIGHT;
            }
          }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, width, height);
          const compressedBase64 = canvas.toDataURL('image/jpeg', 0.7);
          if (type === 'photo') setPhotoPreview(compressedBase64);
          else setSignaturePreview(compressedBase64);
        };
        img.src = reader.result as string;
      };
      reader.readAsDataURL(file);
    }
  };

  const onSubmit = async (data: BiharRationNewData) => {
    try {
      setIsGenerating(true);

      const container = engineRef.current;
      if (!container) throw new Error("Preview container not found");

      const html2canvas = (await import("html2canvas-pro")).default;
      const { jsPDF } = await import('jspdf');

      // Create an off-screen container to render at full 100% scale without scroll issues
      const offScreenContainer = document.createElement('div');
      offScreenContainer.style.position = 'absolute';
      offScreenContainer.style.left = '-9999px';
      offScreenContainer.style.top = '0';
      offScreenContainer.style.width = '210mm'; // Force A4 width
      offScreenContainer.style.backgroundColor = 'white';
      offScreenContainer.innerHTML = container.innerHTML;
      document.body.appendChild(offScreenContainer);

      const templateWrapper = offScreenContainer.firstChild as HTMLElement;
      if (!templateWrapper) throw new Error("Template not found");

      const pages = Array.from(templateWrapper.children).filter(el => el.tagName !== 'STYLE' && el.tagName !== 'SCRIPT') as HTMLElement[];
      const pdf = new jsPDF('p', 'mm', 'a4');

      // Crucial: Wait for fonts to load to prevent text overlapping
      await document.fonts.ready;

      for (let i = 0; i < pages.length; i++) {
        const pageElement = pages[i];

        const canvas = await html2canvas(pageElement, {
          scale: 2, // High resolution
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff',
          windowWidth: 794 // 210mm in pixels at 96dpi
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.95);
        const pdfWidth = pdf.internal.pageSize.getWidth();
        let pdfHeight = (canvas.height * pdfWidth) / canvas.width;
        let finalWidth = pdfWidth;
        const a4Height = pdf.internal.pageSize.getHeight();

        // If page is taller than A4, scale it down to fit perfectly without cutting
        if (pdfHeight > a4Height) {
          const ratio = a4Height / pdfHeight;
          finalWidth = pdfWidth * ratio;
          pdfHeight = a4Height;
        }

        if (i > 0) {
          pdf.addPage();
        }

        pdf.addImage(imgData, 'JPEG', (pdfWidth - finalWidth) / 2, 0, finalWidth, pdfHeight);
      }

      document.body.removeChild(offScreenContainer);
      pdf.save(`Bihar_Ration_Card_${data.applicantNameEn || 'Application'}.pdf`);
    } catch (error: any) {
      console.error('Error generating PDF:', error);
      alert(`Failed to generate PDF. Error: ${error.message}`);
    } finally {
