const formatChartDate = (dateStr: string) => {
  if (dateStr.length === 3) return dateStr;
  try {
    const d = new Date(dateStr);
    return isNaN(d.getTime()) ? dateStr : format(d, "EEE");
  } catch {
    return dateStr;
  }
};

// Animated counter hook
function useCountUp(target: number, duration = 1200) {
  const [count, setCount] = useState(0);
  const rafRef = useRef<number>(0);

  useEffect(() => {
    const start = performance.now();
    const animate = (now: number) => {
      const progress = Math.min((now - start) / duration, 1);
      const ease = 1 - Math.pow(1 - progress, 3);
      setCount(Math.floor(ease * target));
      if (progress < 1) {
        rafRef.current = requestAnimationFrame(animate);
      } else {
        setCount(target);
      }
    };
    rafRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(rafRef.current);
  }, [target, duration]);

  return count;
}

interface StatCardProps {
  title: string;
  value: number;
  displayValue?: string;
  subtitle?: string;
  icon: React.ComponentType<{ size?: number; className?: string }>;
  gradient: string;
  accentColor: string;
  change?: string;
  changePositive?: boolean;
  delay?: number;
  href?: string;
}

function StatCard({
  title,
  value,
  displayValue,
  subtitle,
  icon: Icon,
  gradient,
  accentColor,
  change,
  changePositive = true,
  delay = 0,
  href,
}: StatCardProps) {
  const animatedValue = useCountUp(value);
  const Component = href ? Link : ("div" as React.ElementType);

  return (
    <Component
      href={href}
      className={`stat-card animate-slide-up flex flex-col justify-between ${href ? "hover:scale-[1.01] hover:shadow-md transition-all cursor-pointer" : ""}`}
      style={{
