        </div>
        {subtitle && (
          <div
            className="text-[11px] mt-0.5 flex items-center gap-1 leading-tight"
            style={{ color: "var(--text-muted)" }}
          >
            {subtitle}
          </div>
        )}
      </div>

      {/* Bottom accent line */}
      <div
        className="absolute bottom-0 left-0 h-0.5 rounded-full"
        style={{
          width: "40%",
          background: gradient,
          opacity: 0.5,
        }}
      />
    </Component>
  );
}

