                {/* Live Signature Preview with opacity + rotation */}
                <div>
                  <label className="block mb-1">Live Preview:</label>
                  <div className="border border-slate-200 rounded bg-slate-50 p-2 flex items-center justify-center min-h-[50px]">
                    <img
