                        >
                          <Eye size={14} /> Zoom
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Mode 2: Range Input */}
          {splitMode === "range" && (
            <div className="bg-white p-5 rounded-lg border border-slate-300 space-y-3">
