"use client";

import { useState, useEffect, useCallback } from "react";
import Link from "next/link";
import {
  Plus,
  Loader2,
  Filter,
  ChevronRight,
  Briefcase,
  LayoutGrid,
  List,
  Search,
  MessageCircle,
} from "lucide-react";
import { formatCurrency, formatDate, SERVICE_STATUS_COLORS, PAYMENT_STATUS_COLORS } from "@/lib/utils";
import { useToast } from "@/contexts/ToastContext";
import { useRouter } from "next/navigation";
import PageHeader from "@/components/layout/PageHeader";
import NewServiceDialog from "@/components/services/NewServiceDialog";
import ServiceDetailsDialog from "@/components/services/ServiceDetailsDialog";
import LegacyDialog from "@/components/layout/LegacyDialog";

interface Service {
  id: string;
  serviceType: string;
  status: string;
  fees: number;
  paymentStatus: string;
  createdAt: string;
  deadline?: string | null;
  customer: { id: string; name: string; mobile: string };
}

const STATUS_ORDER = ["PENDING", "SUBMITTED", "PROCESSING", "APPROVED", "DELIVERED"];

const STATUS_LABELS: Record<string, string> = {
  PENDING: "Pending",
  SUBMITTED: "Submitted",
  PROCESSING: "Processing",
  APPROVED: "Approved",
  DELIVERED: "Delivered",
  CANCELLED: "Cancelled",
};

function KanbanBoard({
  services,
  onSelect,
  onStatusChange,
}: {
  services: Service[];
  onSelect: (s: Service) => void;
  onStatusChange: (id: string, newStatus: string) => void;
}) {
  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData("serviceId", id);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // allow drop
  };

  const handleDrop = (e: React.DragEvent, status: string) => {
    e.preventDefault();
    const id = e.dataTransfer.getData("serviceId");
    if (id) onStatusChange(id, status);
  };

  return (
    <div className="flex gap-4 overflow-x-auto pb-4">
      {STATUS_ORDER.map((status) => {
        const cols = services.filter((s) => s.status === status);
        return (
          <div
            key={status}
            className="kanban-column shrink-0"
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, status)}
            style={{ minHeight: "200px" }}
          >
            <div className="flex items-center justify-between mb-3">
              <span className={`badge ${SERVICE_STATUS_COLORS[status]}`}>
                {STATUS_LABELS[status]}
              </span>
              <span
                className="text-xs font-semibold"
                style={{ color: "var(--text-muted)" }}
              >
                {cols.length}
              </span>
            </div>
            {cols.length === 0 ? (
              <div
                className="text-center py-8 text-xs"
                style={{ color: "var(--text-muted)" }}
              >
                No services
              </div>
            ) : (
              cols.map((s) => {
                const isOverdue = s.deadline && new Date(s.deadline).getTime() < new Date().getTime() && !["APPROVED", "DELIVERED", "CANCELLED"].includes(s.status);
                const isDueSoon = s.deadline && new Date(s.deadline).getTime() - new Date().getTime() < 86400000 * 2 && !isOverdue && !["APPROVED", "DELIVERED", "CANCELLED"].includes(s.status); // less than 2 days

                return (
                <div
                  key={s.id}
                  className={`kanban-card cursor-grab active:cursor-grabbing ${isOverdue ? 'border-2 border-red-500 bg-red-50' : (isDueSoon ? 'border-2 border-orange-400 bg-orange-50' : '')}`}
                  draggable
                  onDragStart={(e) => handleDragStart(e, s.id)}
                  onClick={() => onSelect(s)}
                >
                  <div
                    className="font-bold text-sm mb-1 truncate flex items-center justify-between"
                    style={{ color: "var(--text-primary)" }}
                  >
                    <span className="flex items-center gap-1">
                      {s.customer.name}
                      {isOverdue && <span title="Overdue!" className="text-red-500 text-xs text-xl">⚠️</span>}
                    </span>
                    {s.status === "DELIVERED" && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          const msg = encodeURIComponent(`नमस्ते ${s.customer.name}, आपका ${s.serviceType} का काम पूरा हो गया है!`);
                          window.open(`https://wa.me/91${s.customer.mobile}?text=${msg}`, '_blank');
                        }}
                        className="text-green-600 hover:text-green-700 p-1"
                        title="Send WhatsApp Alert"
                      >
                        <MessageCircle size={14} />
                      </button>
                    )}
                  </div>
                  <div
                    className="text-xs mb-2 truncate"
                    style={{ color: "var(--text-secondary)" }}
                  >
                    {s.serviceType}
                  </div>
                  <div className="flex flex-col gap-1 mt-2">
                    <div className="flex items-center justify-between">
                      <span
                        className="text-xs font-semibold"
                        style={{ color: "var(--text-muted)" }}
                      >
                        {formatDate(s.createdAt)}
                      </span>
                      <span className="text-sm font-bold" style={{ color: "var(--brand-primary)" }}>
                        {formatCurrency(s.fees)}
                      </span>
                    </div>
                    {s.deadline && (
                      <div className={`text-[10px] font-bold px-1.5 py-0.5 rounded-sm inline-block self-start ${isOverdue ? 'bg-red-100 text-red-700' : (isDueSoon ? 'bg-orange-100 text-orange-700' : 'bg-slate-100 text-slate-600')}`}>
                        Due: {new Date(s.deadline).toLocaleDateString()}
                      </div>
                    )}
                  </div>
                </div>
                );
              })
            )}
          </div>
        );
      })}
    </div>
  );
}

export default function ServicesPage() {
  const [services, setServices] = useState<Service[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<"kanban" | "list">("kanban");
  const [statusFilter, setStatusFilter] = useState("");
  const [query, setQuery] = useState("");
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [isNewServiceOpen, setIsNewServiceOpen] = useState(false);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkStatus, setBulkStatus] = useState("");
  const [isBulkUpdating, setIsBulkUpdating] = useState(false);
  const [callingNext, setCallingNext] = useState(false);
  const [liveToken, setLiveToken] = useState<string | null>(null);

  const toast = useToast();
  const router = useRouter();

  const callNextToken = async () => {
    setCallingNext(true);
    try {
      const res = await fetch('/api/kiosk/call-next', { method: 'POST' });
      const data = await res.json();
      if (data.token) {
        setLiveToken(data.token);
        toast.success(`Calling: ${data.token} — ${data.customer?.name} (${data.serviceType})`);
        fetchServices();
        setTimeout(() => setLiveToken(null), 6000);
      } else {
        toast.error('No pending kiosk requests in queue');
      }
    } catch {
      toast.error('Failed to call next token');
    } finally {
      setCallingNext(false);
    }
  };

  const fetchServices = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set("status", statusFilter);
      params.set("limit", "100");
      const res = await fetch(`/api/services?${params}`);
      const data = await res.json();
      setServices(data.services || []);
      setTotal(data.total || 0);
    } catch {
      toast.error("Failed to load services");
    } finally {
      setLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => {
    fetchServices();
  }, [fetchServices]);

  const handleStatusChange = async (id: string, newStatus: string) => {
    try {
      // Optimistic update
      setServices((prev) =>
        prev.map((s) => (s.id === id ? { ...s, status: newStatus } : s))
      );
      const res = await fetch(`/api/services/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });
      if (!res.ok) throw new Error("Failed to update status");
      toast.success("Status updated");

      if (newStatus === "APPROVED" || newStatus === "DELIVERED") {
        if (confirm(`Status updated to ${newStatus}! Do you want to notify the customer via WhatsApp?`)) {
          const s = services.find(x => x.id === id);
          if (s && s.customer.mobile) {
            const msg = encodeURIComponent(`Hello ${s.customer.name},\n\nYour service application for *${s.serviceType}* is now *${newStatus}*.\n\nThank you,\nRA Seva Point`);
            window.open(`https://wa.me/91${s.customer.mobile.replace(/\D/g, '').slice(-10)}?text=${msg}`, '_blank');
          }
        }
      }
    } catch {
      toast.error("Status update failed");
      fetchServices(); // Revert on failure
    }
  };

  const handleBulkUpdate = async () => {
    if (!bulkStatus || selectedIds.size === 0) return;
    setIsBulkUpdating(true);
    try {
      const res = await fetch("/api/services/bulk", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids: Array.from(selectedIds), status: bulkStatus })
      });
      if (!res.ok) throw new Error("Bulk update failed");
      toast.success(`${selectedIds.size} services updated`);
      setSelectedIds(new Set());
      setBulkStatus("");
      fetchServices();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setIsBulkUpdating(false);
    }
  };

  const toggleSelection = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const toggleAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(new Set(filtered.map(s => s.id)));
    } else {
      setSelectedIds(new Set());
    }
  };

  const filtered = query
    ? services.filter(
        (s) =>
          s.serviceType.toLowerCase().includes(query.toLowerCase()) ||
          s.customer.name.toLowerCase().includes(query.toLowerCase())
      )
    : services;

  return (
    <div className="page-shell page-shell-list">
      <PageHeader
        title="Services"
        subtitle={`${total} total services`}
        actions={
          <>
            <div
              className="flex rounded-xl p-1 gap-1"
              style={{ background: "var(--bg-secondary)", border: "1px solid var(--border-primary)" }}
            >
              <button
                className={`p-2 rounded-lg transition-all ${view === "kanban" ? "gradient-brand text-white shadow-sm" : "btn-ghost"}`}
                onClick={() => setView("kanban")}
                title="Kanban view"
              >
                <LayoutGrid size={16} />
              </button>
              <button
                className={`p-2 rounded-lg transition-all ${view === "list" ? "gradient-brand text-white shadow-sm" : "btn-ghost"}`}
                onClick={() => setView("list")}
                title="List view"
              >
                <List size={16} />
              </button>
            </div>
            <button className="btn-primary" onClick={() => setIsNewServiceOpen(true)}>
              <Plus size={16} />
              New Service
            </button>
            <button
              className="legacy-button"
              style={{ padding: '6px 12px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '6px', background: liveToken ? '#008000' : '#d4d0c8', color: liveToken ? 'white' : 'black', transition: 'all 0.3s' }}
              onClick={callNextToken}
              disabled={callingNext}
              title="Call next kiosk token"
            >
              {callingNext ? <Loader2 size={14} className="animate-spin" /> : '🔔'}
              {liveToken ? liveToken : 'Call Next'}
            </button>
            <a
              href="/display"
              target="_blank"
              rel="noopener noreferrer"
              className="legacy-button"
              style={{ padding: '6px 12px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '6px' }}
              title="Open TV Display Board"
            >
              🖥️ Display Board
            </a>
          </>
        }
      />

      {/* Filters */}
      <div className="toolbar">
        <div className="search-field">
          <Search size={14} />
          <input
            type="text"
            placeholder="Search service or customer..."
            className="input-field"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
        <select
          className="input-field"
          style={{ maxWidth: "220px" }}
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
        >
          <option value="">All Status</option>
          {STATUS_ORDER.map((s) => (
            <option key={s} value={s}>{STATUS_LABELS[s]}</option>
          ))}
          <option value="CANCELLED">Cancelled</option>
        </select>
      </div>

      {/* Bulk Actions */}
      {selectedIds.size > 0 && view === "list" && (
        <div className="flex items-center gap-3 p-3 mb-4 rounded" style={{ background: '#000080', color: 'white' }}>
          <span className="font-semibold text-sm">{selectedIds.size} selected</span>
          <select 
            className="input-field" style={{ width: '150px', color: 'black' }}
            value={bulkStatus}
            onChange={e => setBulkStatus(e.target.value)}
          >
            <option value="">Change Status...</option>
            {STATUS_ORDER.map(s => <option key={s} value={s}>{STATUS_LABELS[s]}</option>)}
          </select>
          <button 
            className="legacy-button" 
            style={{ fontWeight: 'bold' }}
            onClick={handleBulkUpdate}
            disabled={!bulkStatus || isBulkUpdating}
          >
            {isBulkUpdating ? "Updating..." : "Apply to Selected"}
          </button>
        </div>
      )}

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center h-48">
          <Loader2 size={28} className="animate-spin" style={{ color: "var(--brand-primary)" }} />
        </div>
      ) : filtered.length === 0 ? (
        <div className="empty-state">
          <Briefcase size={56} className="empty-state-icon" />
          <div className="empty-state-title">No services found</div>
          <div className="empty-state-desc">Add your first service to get started</div>
          <button className="btn-primary mt-4" onClick={() => setIsNewServiceOpen(true)}>
            <Plus size={16} />
            New Service
          </button>
        </div>
      ) : view === "kanban" ? (
        <KanbanBoard 
            services={filtered} 
            onSelect={(s) => { setSelectedService(s); setIsDetailsOpen(true); }}
            onStatusChange={handleStatusChange} 
          />
      ) : (
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th style={{ width: '40px' }}>
