                >
                  <td onClick={(e) => toggleSelection(s.id, e)}>
                    <input 
                      type="checkbox" 
                      checked={selectedIds.has(s.id)}
                      onChange={() => {}} // handled by td onClick
                    />
                  </td>
                  <td>
                    <div>
                      <div className="font-semibold text-sm" style={{ color: "var(--text-primary)" }}>
                        {s.customer.name}
                      </div>
                      <div className="text-xs" style={{ color: "var(--text-muted)" }}>
                        {s.customer.mobile}
                      </div>
                    </div>
                  </td>
                  <td className="text-sm" style={{ color: "var(--text-secondary)" }}>
                    {s.serviceType}
                  </td>
                  <td>
                    <span className={`badge ${SERVICE_STATUS_COLORS[s.status]}`}>
                      {s.status}
                    </span>
                  </td>
                  <td>
                    <span className={`badge ${PAYMENT_STATUS_COLORS[s.paymentStatus]}`}>
                      {s.paymentStatus}
                    </span>
                  </td>
                  <td className="font-semibold text-sm" style={{ color: "var(--text-primary)" }}>
                    {formatCurrency(s.fees)}
                  </td>
                  <td className="text-sm" style={{ color: "var(--text-muted)" }}>
                    {formatDate(s.createdAt)}
                  </td>
                  <td>
                    <ChevronRight size={16} style={{ color: "var(--text-muted)" }} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <NewServiceDialog
        isOpen={isNewServiceOpen}
        onClose={() => setIsNewServiceOpen(false)}
        onSuccess={fetchServices}
      />

      <ServiceDetailsDialog
        isOpen={isDetailsOpen}
        onClose={() => { setIsDetailsOpen(false); setSelectedService(null); }}
        serviceId={selectedService?.id || null}
        onSuccess={() => {
          setIsDetailsOpen(false);
          setSelectedService(null);
          fetchServices();
        }}
      />
    </div>
  );
}

