"use client";

import { useState, useEffect } from "react";
import { Plus, Edit2, Trash2, ChevronDown, ChevronUp, Link as LinkIcon, Loader2 } from "lucide-react";
import { useToast } from "@/contexts/ToastContext";
import PageHeader from "@/components/layout/PageHeader";

export default function OnlineServicesAdminPage() {
  const [categories, setCategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedCat, setExpandedCat] = useState<string | null>(null);
  const toast = useToast();

  const fetchCategories = async () => {
    try {
      const res = await fetch("/api/online-services");
      const data = await res.json();
      setCategories(data);
    } catch (err) {
      toast.error("Failed to load services");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const handleDeleteCategory = async (id: string) => {
    if (!confirm("Delete this category?")) return;
    try {
      await fetch(`/api/online-services/${id}`, { method: "DELETE" });
      fetchCategories();
      toast.success("Deleted category");
    } catch {
      toast.error("Error deleting category");
    }
  };

  const handleDeleteLink = async (catId: string, linkId: string) => {
    if (!confirm("Delete this link?")) return;
    try {
      await fetch(`/api/online-services/${catId}/links/${linkId}`, { method: "DELETE" });
      fetchCategories();
      toast.success("Deleted link");
    } catch {
      toast.error("Error deleting link");
    }
  };

  if (loading) return <div className="flex justify-center p-8"><Loader2 className="animate-spin" /></div>;

  return (
    <div className="page-shell">
      <PageHeader title="Online Services Admin" subtitle="Manage categories and sub-links for Online Work page" />

      <div className="mb-4">
        <button className="btn btn-primary" onClick={() => {
          const title = prompt("Category Title?");
          if (title) {
             fetch("/api/online-services", {
               method: "POST",
               body: JSON.stringify({ title, order: categories.length + 1 }),
               headers: { "Content-Type": "application/json" }
             }).then(fetchCategories);
          }
        }}>
          <Plus size={16} /> Add Category
        </button>
      </div>

      <div className="space-y-4">
        {categories.map((cat) => (
          <div key={cat.id} className="glass-card overflow-hidden">
            <div className="flex justify-between items-center p-4 bg-black/20">
              <div className="flex items-center gap-3 cursor-pointer" onClick={() => setExpandedCat(expandedCat === cat.id ? null : cat.id)}>
                {expandedCat === cat.id ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
                <span className="font-semibold">{cat.order}. {cat.title}</span>
              </div>
              <div className="flex gap-2">
                <button className="icon-btn text-blue-400" onClick={() => {
                  const title = prompt("New title?", cat.title);
                  if (title) {
                    fetch(`/api/online-services/${cat.id}`, {
                      method: "PUT",
                      body: JSON.stringify({ ...cat, title }),
                      headers: { "Content-Type": "application/json" }
                    }).then(fetchCategories);
                  }
                }}><Edit2 size={16} /></button>
                <button className="icon-btn text-red-400" onClick={() => handleDeleteCategory(cat.id)}><Trash2 size={16} /></button>
              </div>
            </div>

            {expandedCat === cat.id && (
              <div className="p-4 border-t border-white/10">
                <div className="mb-3">
                  <button className="btn btn-secondary text-sm" onClick={() => {
                    const title = prompt("Link Title?");
                    const href = prompt("URL?");
                    if (title && href) {
                       fetch(`/api/online-services/${cat.id}/links`, {
                         method: "POST",
                         body: JSON.stringify({ title, href, order: cat.links.length + 1 }),
                         headers: { "Content-Type": "application/json" }
                       }).then(fetchCategories);
                    }
                  }}>
                    <Plus size={14} /> Add Link
                  </button>
                </div>
                <div className="space-y-2">
                  {cat.links?.map((link: any) => (
                    <div key={link.id} className="flex justify-between items-center bg-black/10 p-2 rounded">
                      <div className="flex items-center gap-2 text-sm text-gray-300">
                        <LinkIcon size={14} />
                        {link.title} - <span className="text-gray-500">{link.href}</span>
                      </div>
                      <div className="flex gap-2">
                        <button className="icon-btn text-blue-400 p-1" onClick={() => {
                          const title = prompt("New title?", link.title) || link.title;
                          const href = prompt("New URL?", link.href) || link.href;
                          fetch(`/api/online-services/${cat.id}/links/${link.id}`, {
                            method: "PUT",
                            body: JSON.stringify({ ...link, title, href }),
                            headers: { "Content-Type": "application/json" }
                          }).then(fetchCategories);
                        }}><Edit2 size={14} /></button>
                        <button className="icon-btn text-red-400 p-1" onClick={() => handleDeleteLink(cat.id, link.id)}><Trash2 size={14} /></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/db';

export async function POST(request: Request) {
  try {
    const formData = await request.formData();
    const file = formData.get('image') as File | null;

    if (!file) {
      return NextResponse.json({ error: 'No image provided' }, { status: 400 });
    }

    // 1. Fetch API Keys from Settings
    const setting = await prisma.shopSettings.findUnique({ where: { key: 'geminiApiKeys' } });
    let apiKeys: string[] = [];
    try {
      if (setting?.value) {
        apiKeys = JSON.parse(setting.value);
      }
    } catch (e) {
      console.error("Error parsing API keys from settings", e);
    }

    // 2. Fallback Simulator if no keys are provided
    if (apiKeys.length === 0) {
      await new Promise(resolve => setTimeout(resolve, 2000));
      return NextResponse.json({ 
        success: true, 
        message: 'Simulator Mode: No API keys configured. Returning mock data.',
        data: {
          name: "Ramesh Kumar",
          mobile: "9876543210", 
          address: "123, Model Town, Delhi - 110009",
          aadhaarNumber: "1234 5678 9012",
          panNumber: "ABCDE1234F"
        } 
      });
    }

    // 3. Prepare Image for Gemini API
    const buffer = await file.arrayBuffer();
    const base64Image = Buffer.from(buffer).toString('base64');
    const mimeType = file.type;

    const requestPayload = {
      contents: [{
        parts: [
          {
            text: "Extract the name, mobile number, address, aadhaar number, and PAN number from this ID card. Return ONLY a valid JSON object with keys: name, mobile, address, aadhaarNumber, panNumber. If a field is not found, leave it empty."
          },
          {
            inline_data: {
              mime_type: mimeType,
              data: base64Image
            }
          }
        ]
      }],
      generationConfig: {
        response_mime_type: "application/json"
      }
    };

    // 4. API Key Rotation Logic
    let lastError = null;

    for (let i = 0; i < apiKeys.length; i++) {
      const currentKey = apiKeys[i];

      try {
        const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${currentKey}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(requestPayload)
        });

        if (response.status === 429) {
          console.warn(`[AI Rotation] Key #${i + 1} hit quota limit (429). Switching to next key...`);
          lastError = new Error("Quota exceeded");
          continue; // Try next key
        }

        if (!response.ok) {
          const errorText = await response.text();
          console.error(`[AI Rotation] Key #${i + 1} failed with status ${response.status}`, errorText);
          lastError = new Error(`API Error: ${response.status}`);
          continue; // Try next key (might be a bad key)
        }

        const data = await response.json();
        const textResult = data.candidates?.[0]?.content?.parts?.[0]?.text;

        if (!textResult) throw new Error("Empty response from AI");

        // Parse the JSON strictly
        const parsedData = JSON.parse(textResult);

        return NextResponse.json({
          success: true,
          message: `Processed successfully using Key #${i + 1}`,
          data: {
            name: parsedData.name || "",
            mobile: parsedData.mobile || "",
            address: parsedData.address || "",
            aadhaarNumber: parsedData.aadhaarNumber || "",
            panNumber: parsedData.panNumber || ""
          }
        });

      } catch (err: any) {
        console.error(`[AI Rotation] Exception with Key #${i + 1}:`, err);
        lastError = err;
        // Continue to next key
      }
    }

    // 5. If all keys fail
    return NextResponse.json({ 
      error: 'All configured API keys failed or exceeded quota. Please check Settings.' 
    }, { status: 500 });

  } catch (error) {
    console.error('OCR Error:', error);
    return NextResponse.json({ error: 'Failed to process image' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
