export async function GET(req: Request) {
  try {
    // Delete files older than 24 hours
    const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

    const result = await prisma.fileDrop.deleteMany({
      where: {
        createdAt: {
          lt: twentyFourHoursAgo
        }
      }
